func TestOpen(t *testing.T) {
	tests := []struct {
		name    string
		cfg     config.Config
		driver  Driver
		wantErr bool
	}{
		{
			name: "sqlite",
			cfg: config.Config{
				Database: config.DatabaseConfig{
					URL:             "file:flipt.db",
					MaxOpenConn:     5,
					ConnMaxLifetime: 30 * time.Minute,
				},
			},
			driver: SQLite,
		},
		{
			name: "postres",
			cfg: config.Config{
				Database: config.DatabaseConfig{
					URL: "postgres://postgres@localhost:5432/flipt?sslmode=disable",
				},
			},
			driver: Postgres,
		},
		{
			name: "mysql",
			cfg: config.Config{
				Database: config.DatabaseConfig{
					URL: "mysql://mysql@localhost:3306/flipt",
				},
			},
			driver: MySQL,
		},
		{
			name: "invalid url",
			cfg: config.Config{
				Database: config.DatabaseConfig{
					URL: "http://a b",
				},
			},
			wantErr: true,
		},
		{
			name: "unknown driver",
			cfg: config.Config{
				Database: config.DatabaseConfig{
					URL: "mongo://127.0.0.1",
				},
			},
			wantErr: true,
		},
	}

	for _, tt := range tests {
		var (
			cfg     = tt.cfg
			driver  = tt.driver
			wantErr = tt.wantErr
		)

		t.Run(tt.name, func(t *testing.T) {
			db, d, err := Open(cfg)

			if wantErr {
				require.Error(t, err)
				return
			}

			require.NoError(t, err)
			require.NotNil(t, db)

			defer db.Close()

			assert.Equal(t, driver, d)
		})
	}
}

func TestParse(t *testing.T) {
	tests := []struct {
		name    string
		input   string
		dsn     string
		driver  Driver
		wantErr bool
	}{
		{
			name:   "sqlite",
			input:  "file:flipt.db",
			driver: SQLite,
			dsn:    "flipt.db?_fk=true&cache=shared",
		},
		{
			name:   "postres",
			input:  "postgres://postgres@localhost:5432/flipt?sslmode=disable",
			driver: Postgres,
			dsn:    "dbname=flipt host=localhost port=5432 sslmode=disable user=postgres",
		},
		{
			name:   "mysql",
			input:  "mysql://mysql@localhost:3306/flipt",
			driver: MySQL,
			dsn:    "mysql@tcp(localhost:3306)/flipt?multiStatements=true&parseTime=true&sql_mode=ANSI",
		},
		{
			name:    "invalid url",
			input:   "http://a b",
			wantErr: true,
		},
		{
			name:    "unknown driver",
			input:   "mongo://127.0.0.1",
			wantErr: true,
		},
	}

	for _, tt := range tests {
		var (
			input   = tt.input
			driver  = tt.driver
			url     = tt.dsn
			wantErr = tt.wantErr
		)

		t.Run(tt.name, func(t *testing.T) {
			d, u, err := parse(input, false)

			if wantErr {
				require.Error(t, err)
				return
			}

			require.NoError(t, err)
			assert.Equal(t, driver, d)
			assert.Equal(t, url, u.DSN)
		})
	}
}

